def calc(items, customer_tier):
    DISCOUNTS = {
        "GOLD": 0.2,
        "SILVER": 0.1,
        "BRONZE": 0.05
    }

    subtotal = sum(unit_price * quantity for unit_price, quantity in items)
    discount_rate = DISCOUNTS.get(customer_tier, 0)
    total = subtotal * (1 - discount_rate)
    total = max(total, 0)
    return round(total, 2)
```

